import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  random,
  Sequence,
} from '../remotionShim';
import { Star } from "@remotion/shapes";
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type MillionDollarGoalProps = Record<string, any>;

const Particle: React.FC<{
  index: number;
  total: number;
  width: number;
  height: number;
  color: string;
  frame: number;
}> = ({ index, width, height, color, frame }) => {
  const seed = random(index);
  const size = interpolate(seed, [0, 1], [10, 40]);
  const xBase = interpolate(random(index + 100), [0, 1], [-width * 0.2, width * 1.2]);
  const yBase = interpolate(random(index + 200), [0, 1], [-height * 0.2, height * 1.2]);
  
  // Floating movement
  const yOffset = Math.sin(frame / 50 + seed * 10) * 30;
  const rotate = interpolate(frame, [0, 300], [0, 360 * (seed > 0.5 ? 1 : -1)]);
  const opacity = interpolate(
    Math.sin(frame / 40 + seed * 10),
    [-1, 1],
    [0.2, 0.6]
  );

  return (
    <div
      style={{
        position: "absolute",
        left: xBase,
        top: yBase + yOffset,
        opacity,
        transform: `rotate(${rotate}deg)`,
      }}
    >
      <Star
        points={5}
        outerRadius={size}
        innerRadius={size * 0.4}
        fill={color}
      />
    </div>
  );
};

const MillionDollarGoal: React.FC<MillionDollarGoalProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#FFD700",
  secondaryColor = "#2ECC71",
  textColor = "#FFFFFF",
  titleText = "A MILLION DOLLARS",
  subtitleText = "IN THE NEXT",
  highlightText = "90 DAYS",
  particleCount = 30,
}) => {
  useFontLoader(["Oswald", "Montserrat"]);
  
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animations ---

  // Title Animation (Scale + Slide Up)
  const titleDelay = 10;
  const titleSpring = spring({
    frame: frame - titleDelay,
    fps,
    config: { damping: 12 },
  });
  const titleOpacity = interpolate(frame, [titleDelay, titleDelay + 20], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const titleY = interpolate(titleSpring, [0, 1], [50, 0]);

  // Subtitle Animation (Fade In)
  const subDelay = 35;
  const subOpacity = interpolate(frame, [subDelay, subDelay + 20], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const subX = interpolate(frame, [subDelay, subDelay + 30], [-50, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: (t) => t * (2 - t), // Ease out quad
  });

  // Highlight Animation (Stamp Effect)
  const highDelay = 50;
  const highScale = spring({
    frame: frame - highDelay,
    fps,
    config: { stiffness: 200, damping: 10, mass: 0.8 },
  });
  const highOpacity = interpolate(frame, [highDelay, highDelay + 10], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Background Particles
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => i);
  }, [particleCount]);

  // Styles
  const containerStyle: React.CSSProperties = {
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    fontFamily: "Oswald, sans-serif",
    textAlign: "center",
    zIndex: 10,
  };

  const titleStyle: React.CSSProperties = {
    fontSize: Math.min(width, height) * 0.12,
    fontWeight: 900,
    color: primaryColor,
    lineHeight: 1.1,
    textTransform: "uppercase",
    opacity: titleOpacity,
    transform: `translateY(${titleY}px) scale(${0.8 + titleSpring * 0.2})`,
    textShadow: `0 0 20px ${primaryColor}40`,
    marginBottom: height * 0.02,
  };

  const subStyle: React.CSSProperties = {
    fontSize: Math.min(width, height) * 0.05,
    fontFamily: "Montserrat, sans-serif",
    fontWeight: 700,
    color: textColor,
    letterSpacing: "0.2em",
    textTransform: "uppercase",
    opacity: subOpacity,
    transform: `translateX(${subX}px)`,
    marginBottom: height * 0.02,
  };

  const highStyle: React.CSSProperties = {
    fontSize: Math.min(width, height) * 0.18,
    fontWeight: 900,
    color: secondaryColor,
    lineHeight: 0.9,
    textTransform: "uppercase",
    opacity: highOpacity,
    transform: `scale(${highScale})`,
    textShadow: `0 10px 30px ${secondaryColor}66`,
    border: `8px solid ${secondaryColor}`,
    padding: "10px 40px",
    borderRadius: 10,
    background: `${secondaryColor}10`, // Slight tint background
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Particles */}
      {!transparentBackground && (
        <AbsoluteFill>
          {particles.map((i) => (
            <Particle
              key={i}
              index={i}
              total={particleCount}
              width={width}
              height={height}
              color={i % 2 === 0 ? primaryColor : "#ffffff"}
              frame={frame}
            />
          ))}
        </AbsoluteFill>
      )}

      {/* Main Content */}
      <div style={containerStyle}>
        
        {/* Title */}
        <div style={titleStyle}>
          {titleText}
        </div>

        {/* Subtitle */}
        <div style={subStyle}>
          {subtitleText}
        </div>

        {/* Highlight Box */}
        <div style={highStyle}>
          {highlightText}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default MillionDollarGoal;